'@ | ConvertFrom-Json
foreach ($f in $files) {
  $full = Join-Path $root $f.path
  $dir = Split-Path -Parent $full
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  $newContent = [string]$f.content
  $write = $true
  if (Test-Path $full) {
    $oldContent = Get-Content -Raw -Path $full
    if ($oldContent -eq $newContent) { $write = $false }
  }
  if ($write) { Set-Content -Path $full -Value $newContent -Encoding UTF8 }
}
$manifestItems = foreach ($f in $files) {
  $full = Join-Path $root $f.path
  $hash = (Get-FileHash -Algorithm SHA256 -Path $full).Hash
  [PSCustomObject]@{ path = $f.path; sha256 = $hash }
}
$manifestPath = Join-Path $root "manifest.sha256.json"
$manifestItems | ConvertTo-Json -Depth 4 | Set-Content -Path $manifestPath -Encoding UTF8
$proofHash = (Get-FileHash -Algorithm SHA256 -Path $manifestPath).Hash
$proofPath = Join-Path $root "SEALED.proof.artifact"
@{ sealed = $true; manifest = "manifest.sha256.json"; manifest_sha256 = $proofHash; stamp_utc = (Get-Date).ToUniversalTime().ToString("o") } | ConvertTo-Json -Depth 4 | Set-Content -Path $proofPath -Encoding UTF8
Write-Output 'pwsh -NoProfile -Command "$m=Get-Content -Raw manifest.sha256.json | ConvertFrom-Json; foreach($i in $m){ if((Get-FileHash -Algorithm SHA256 $i.path).Hash -ne $i.sha256){ throw "hash mismatch: $($i.path)" } }; (Get-Content -Raw SEALED.proof.artifact | ConvertFrom-Json).sealed"'
